select s.name, s.version_no, s.status, s.readiness_status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.skill_code = 'command_of_evidence_quant') as quant_items
from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.name = any (array['SAT Practice Test 6','SAT Practice Test 10','SAT Practice Test 11','SAT Practice Test 12','SAT Practice Test 13','SAT Practice Test 16','SAT Practice Test 17','SAT Practice Test 18','SAT Practice Test 19','SAT Practice Test 20','SAT Practice Test 22','SAT Practice Test 23','SAT Practice Test 24','SAT Practice Test 25','SAT Practice Test 27','SAT Practice Test 30']) order by length(s.name), s.name;
